import type { Notification } from '@/entities/notification/types'
import { clsx } from 'clsx'
import { formatDistanceToNow } from 'date-fns'

type Props = { notification: Notification; onRead: (id: string) => void }

export function NotificationItem({ notification, onRead }: Props) {
  return (
    <button
      onClick={() => onRead(notification.id)}
      className={clsx(
        'w-full text-left px-4 py-3 border-b border-border last:border-0 hover:bg-muted/50 transition-colors',
        !notification.read && 'bg-accent/5',
      )}
    >
      <div className="flex items-start gap-2">
        {!notification.read && (
          <span className="mt-1.5 h-1.5 w-1.5 rounded-full bg-accent flex-shrink-0" />
        )}
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium truncate">{notification.title}</p>
          <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">{notification.body}</p>
          <p className="text-xs text-muted-foreground/60 mt-1">
            {formatDistanceToNow(new Date(notification.createdAt), { addSuffix: true })}
          </p>
        </div>
      </div>
    </button>
  )
}
